from itertools import product
def interps(n):
    D = range(n)
    for M in product([0, 1], repeat=n):
        for B in product([0, 1], repeat=n):
            for Ev in product([0, 1], repeat=n * n):
                yield D, M, B, (lambda x, y, Ev=Ev: Ev[x * n + y])
